sub normal_density {
    my $x = shift;
    return exp(-0.5 * $x * $x) / sqrt(2 * 3.14159265359);
}

sub exponential_density {
    my $x = shift;
    return $x >= 0 ? exp(-$x) : 0;
}

sub gamma_density {
    my $x = shift;
    return $x >= 0 ? $x * exp(-$x) : 0;
}

